const handleBulkDownloadZip = async () => {
  if (!organization?.slug || !organization?.name) {
    setError('Organizasyon bilgileri eksik')
    return
  }

  if (tables.length === 0) {
    setError('İndirilecek masa bulunamadı')
    return
  }

  try {
    const result = await downloadAllTablesAsZip(
      tables.map((t) => ({ qr_uuid: t.qr_uuid, table_number: t.table_number })),
      organization.slug,
      organization.name
    )

    if (!result.success) {
      setError(result.error || 'QR kodları indirilirken bir hata oluştu')
    }
  } catch {
    setError('QR kodları indirilirken bir hata oluştu')
  }
}

